const expectedSecret = $env.N8N_WEBHOOK_SECRET;
const providedSecret = $json.headers?.['x-servicioscreativos-secret'];

if (!expectedSecret || providedSecret !== expectedSecret) {
  return [{ json: { ok: false, error: expectedSecret ? 'Unauthorized.' : 'Workflow secret is not configured.', statusCode: expectedSecret ? 401 : 503 } }];
}

const body = $json.body ?? $json;
if (body.event === 'meta_embedded_signup_diagnostic' || body.diagnostic === true) {
  return [{ json: { ok: true, diagnostic: true, reached_n8n: true, received_at: new Date().toISOString() } }];
}

if (body.event === 'meta_app_deauthorized' || body.event === 'meta_user_data_deletion_requested') {
  if (!body.user_id) return [{ json: { ok: false, error: 'user_id is required.', statusCode: 400 } }];
  return [{ json: { ok: true, processed: true, event: body.event, user_id: body.user_id, processed_at: new Date().toISOString() } }];
}

return [{ json: { ok: false, error: 'Signup credentials are accepted only by the encrypted allok database.', statusCode: 410 } }];
